      "claim_type": "inferred_claim",
      "record_ids": ["S08-00001", "S08-00002", "S08-00021", "S08-00022", "S08-00034", "S08-00035"]
    },
    {
      "claim": "At 13:59 UTC, WS-RIYER-01 logged an explicit-credentials event in which a SYSTEM process, taskhostw.exe, targeted svc-reporting at DC-LV-01. This is distinct from the FILE-LV-01 failure pattern and is unexplained by the available records.",
      "claim_type": "observed_fact",
      "record_ids": ["S08-00036"]
    }
  ],
  "known_telemetry_limitations": [
